#include <bits/stdc++.h>
using namespace std;

int main() 
{
    ios :: sync_with_stdio(false);
    cin.tie(nullptr);
    
	int t;
	cin >> t;
	while(t--)
	{
	    int n;
	    cin>>n;
	    int m = 3 * n;
	    vector<long long> a(m), p(m+1);
	    
	    for(auto &x : a)
	        cin >> x;
	   
	    sort(a.rbegin() , a.rend());
	    
	    for(int i = 0; i<m; i++)
	        p[i+1] = p[i] + a[i];
	        
	    auto val = [&](int x , int y)
	    {
	        int z = n - x -y;
	        int q = x + 2 * y;
	        int r = q + 3 * z;
	        
	        return 6 * p[x] + 4 * (p[q] - p[x]) + 3 * (p[r] - p[q]);
	    };
	    
	    long long ans = 0;
	    
	    for(int x = 0; x<= n; x++)
	    {
	        int l = 0 , r = n -x;
	        
	        while(l<r)
	        {
	            int y = (l+r) / 2;
	            
	            int q = x + 2 * y;
	            int z = n -x - y;
	            int rr = q + 3 * z;
	            
	            long long d = a[q] + a[q+1] - 3 * a[rr-1];
	            
	            if( d>= 0)
	                l = y + 1;
	            else
	                r = y;
	        }
	        
	        ans = max(ans, val(x , l ));
	        
	        if(l=1)
	            ans = max(ans, val(x , l-1));
	            
	    }
	    cout << ans << '\n';
	    
	}
	return 0;

}
